use std::collections::BTreeMap;

use crate::api::client::ApiClient;
use chrono::{Datelike, NaiveDate, Utc};

use crate::{
    models::{ResultWithDefaultError, TimeEntry},
    utilities,
};

pub struct BillWeeklyCommand;

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let weekly = billable_seconds_by_week(&entries);

        if weekly.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = weekly.values().sum();
        for (week, seconds) in weekly {
            println!("{week}  {seconds}s");
        }
        println!("Total  {total}s");
        Ok(())
    }
}

fn billable_seconds_by_week(entries: &[TimeEntry]) -> BTreeMap<NaiveDate, i64> {
    let mut weekly = BTreeMap::new();

    for entry in entries {
        // The billing rule applies only to stopped, billable entries. Running
        // entries have a negative duration and are never included.
        if !entry.billable || entry.stop.is_none() || entry.duration <= 0 {
            continue;
        }

        let start_date = entry.start.with_timezone(&Utc).date_naive();
        let week =
            start_date - chrono::Duration::days(start_date.weekday().num_days_from_monday() as i64);
        *weekly.entry(week).or_insert(0) += entry.duration;
    }

    weekly
}

